referenceSolutions.javascript:
export function solve(operations) {
  const store = new Map();
  return operations.map(([op, time, key, value, ttl]) => {
    if (op === "set") {
      store.set(key, { value, expires: time + ttl });
      return null;
    }
    if (op === "remove") {
      store.delete(key);
      return null;
    }
    const item = store.get(key);
    return item && time < item.expires ? item.value : null;
  });
}

